package com.yeyamo_mobile.api.partner_service.infrastructure.messaging;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.partner_service.application.port.PartnerOutboxPort;
@Component public class JpaPartnerOutboxAdapter implements PartnerOutboxPort{private final PartnerOutboxRepository repo;private final ObjectMapper mapper;public JpaPartnerOutboxAdapter(PartnerOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,UUID partner,String actor,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Instant now=Instant.now();Map<String,Object>e=new LinkedHashMap<>();e.put("eventId",id);e.put("eventType",type);e.put("eventVersion",1);e.put("occurredAt",now);e.put("producer","partner-service");e.put("correlationId",correlation);e.put("actorId",actor);e.put("payload",payload);PartnerOutboxEvent row=new PartnerOutboxEvent();row.setId(id);row.setAggregateId(partner);row.setEventType(type);row.setPayload(mapper.writeValueAsString(e));row.setOccurredAt(now);repo.save(row);}catch(Exception ex){throw new IllegalStateException("Unable to serialize partner event",ex);}}}
